Evaluate the JavaScript Conway's Game of Life implementation on a scale of 0-10 points:

**Feature Completeness (4 points)**: Does it implement all required features - emoji cells with aging system, famous patterns (Glider, Blinker, Gosper Gun, Pulsar), speed control, click-to-toggle, randomize/clear buttons, and death animations?

**Game Logic Accuracy (3 points)**: Does it correctly implement Conway's Game of Life rules? Are the cellular automata calculations accurate and the patterns behaving as expected?

**Performance & Interaction (2 points)**: Does it run smoothly at 60 FPS? Are the controls responsive and the animations fluid?

**Code Quality (1 point)**: Is the code well-structured, efficient, and following JavaScript best practices?

Solution A: <script>
function runLife(canvasId) {
  const canvas = document.getElementById(canvasId);
  if (!canvas || !(canvas instanceof HTMLCanvasElement)) return;
  const ctx = canvas.getContext('2d');
  const cellSize = 10;
  const cols = canvas.width / cellSize;
  const rows = canvas.height / cellSize;

  // Create UI
  const ui = document.createElement('div');
  ui.style.marginBottom = '10px';
  document.body.insertBefore(ui, canvas);

  const patternSelect = document.createElement('select');
  ['Glider','Blinker','Gosper Gun','Pulsar'].forEach(p => {
    const opt = document.createElement('option'); opt.value=p; opt.textContent=p; patternSelect.appendChild(opt);
  });
  ui.appendChild(patternSelect);

  const speedLabel = document.createElement('label'); speedLabel.textContent=' Speed: ';
  const speedSlider = document.createElement('input'); speedSlider.type='range'; speedSlider.min=1; speedSlider.max=10; speedSlider.value=5;
  speedLabel.appendChild(speedSlider); ui.appendChild(speedLabel);

  const randBtn = document.createElement('button'); randBtn.textContent='Randomize'; ui.appendChild(randBtn);
  const clearBtn = document.createElement('button'); clearBtn.textContent='Clear'; ui.appendChild(clearBtn);
  const startBtn = document.createElement('button'); startBtn.textContent='Start'; ui.appendChild(startBtn);
  const stopBtn = document.createElement('button'); stopBtn.textContent='Stop'; ui.appendChild(stopBtn);

  const emojis = {
    age0: '🟢',
    age1: '🟠',
    age2: '🟡',
    dying: '❌'
  };
  const deathDuration = 200; // ms

  let grid = Array.from({length: rows}, () => Array.from({length: cols}, () => ({alive:false, age:0, dying:false})));
  let newGrid;
  let running = false;
  let lastGenTime = 0;
  let genInterval = 1000 / parseInt(speedSlider.value);

  function neighbors(r,c){
    let cnt=0; let da=0;
    for(let dr=-1;dr<=1;dr++){
      for(let dc=-1;dc<=1;dc++){
        if(dr===0&&dc===0)continue;
        const nr=r+dr,nc=c+dc;
        if(nr>=0&&nr<rows&&nc>=0&&nc<cols&&grid[nr][nc].alive){cnt++;da+=grid[nr][nc].age;}
      }
    }
    return {cnt, da};
  }

  function step(){
    newGrid = Array.from({length: rows}, () => Array.from({length: cols}, () => ({alive:false, age:0, dying:false})));
    for(let r=0;r<rows;r++){
      for(let c=0;c<cols;c++){
        const cell = grid[r][c];
        const {cnt, da} = neighbors(r,c);
        if(cell.alive){
          if(cnt===2||cnt===3){
            newGrid[r][c].alive=true;
            newGrid[r][c].age=cell.age+1;
          }else{
            newGrid[r][c].dying=true;
            newGrid[r][c].deathStart=performance.now();
          }
        }else{
          if(cnt===3){
            newGrid[r][c].alive=true;
            newGrid[r][c].age=1;
          }
        }
      }
    }
    grid = newGrid;
  }

  function draw(){
    ctx.clearRect(0,0,canvas.width,canvas.height);
    for(let r=0;r<rows;r++){
      for(let c=0;c<cols;c++){
        const cell = grid[r][c];
        if(cell.alive){
          let emoji;
          if(cell.age===0)emoji=emojis.age0;
          else if(cell.age===1)emoji=emojis.age1;
          else emoji=emojis.age2;
          ctx.fillText(emoji, c*cellSize+2, r*cellSize+8);
        }else if(cell.dying){
          const elapsed=performance.now()-cell.deathStart;
          if(elapsed<deathDuration){
            ctx.globalAlpha=1-(elapsed/deathDuration);
            ctx.fillText(emojis.dying, c*cellSize+2, r*cellSize+8);
            ctx.globalAlpha=1;
          }else{
            newGrid[r][c].alive=false;
          }
        }
      }
    }
  }

  function loop(now){
    if(!running)return;
    if(now-lastGenTime>=genInterval){
      step();
      lastGenTime=now;
    }
    draw();
    requestAnimationFrame(loop);
  }

  patternSelect.addEventListener('change', () => {
    const pat = patternSelect.value;
    clearGrid();
    switch(pat){
      case 'Glider':
        placePattern([[0,1],[1,2],[2,0],[2,1],[2,2]]);
        break;
      case 'Blinker':
        placePattern([[1,0],[1,1],[1,2]]);
        break;
      case 'Pulsar':
        const base=[[-2,-2],[-3,-2],[-4,-2],[-4,-3],[-4,-4],[-3,-4],[-2,-4],[-2,-5],[-3,-5],[-4,-5],[-5,-2],[-5,-3],[-5,-4],[-5,-5],[-2,2],[-3,2],[-4,2],[-4,3],[-4,4],[-3,4],[-2,4],[-2,5],[-3,5],[-4,5],[-5,2],[-5,3],[-5,4],[-5,5]];
        placePattern(base);
        break;
      case 'Gosper Gun':
        const gun=[ [0,0],[0,1],[1,0],[1,1],[10,0],[10,1],[11,0],[11,1],[10,2],[11,2],[12,0],[12,1],[12,2],[13,1],[23,0],[23,1],[24,0],[24,1],[25,0],[25,1],[34,0],[34,1],[34,2],[35,0],[35,1],[35,2],[0,10],[1,10],[2,10],[3,10],[4,10],[5,10],[0,11],[1,11],[2,11],[3,11],[4,11],[5,11],[9,10],[9,11],[0,12],[5,12],[0,13],[5,13],[0,15],[5,15],[10,25],[11,25],[10,26],[11,26],[10,27],[11,27],[20,25],[20,26],[20,27],[21,25],[21,26],[21,27],[0,21],[1,21],[0,22],[1,22],[0,24],[1,24],[0,24],[0,30],[1,30],[2,30],[3,30],[4,30],[5,30],[6,30],[7,30],[8,30],[9,30],[9,29],[1,31],[9,31],[0,30],[9,32],[0,31],[9,33],[7,30],[1,33],[2,33],[9,33],[6,32],[0,27],[8,30],[7,33],[4,30],[7,34],[5,37],[6,37],[6,38],[7,38],[7,40],[9,40],[6,42],[7,42],[8,42],[6,44],[8,44],[5,46],[5,47],[6,48],[10,48],[11,48],[12,48],[10,49],[11,49],[12,49],[10,46],[12,46],[8,46],[8,47],[9,46],[10,46],[8,48],[9,48],[10,48],[8,49],[9,49],[10,49],[8,51],[9,51],[10,51],[11,51],[12,51],[7,51],[7,52],[7,53],[7,55],[7,56],[7,58],[7,59]];
        placePattern(gun);
        break;
    }
  });

  function placePattern(coords){
    const startX=Math.floor(cols/2);
    const startY=Math.floor(rows/2);
    coords.forEach(([dy,dx])=>{
      const r=startY+dy;
      const c=startX+dx;
      if(r>=0&&r<rows&&c>=0&&c<cols){
        grid[r][c].alive=true;
        grid[r][c].age=1;
      }
    });
  }

  function clearGrid(){
    for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){grid[r][c].alive=false;grid[r][c].age=0;grid[r][c].dying=false;}
  }

  speedSlider.addEventListener('input', () => {
    genInterval=1000/parseInt(speedSlider.value);
  });

  randBtn.addEventListener('click', ()=>{
    for(let r=0;r<rows;r++){
      for(let c=0;c<cols;c++){
        const alive=Math.random()<0.3;
        grid[r][c].alive=alive;
        grid[r][c].age=alive?1:0;
        grid[r][c].dying=false;
      }
    }
  });

  clearBtn.addEventListener('click', clearGrid);
  startBtn.addEventListener('click', ()=>{
    if(!running){running=true;lastGenTime=performance.now(); requestAnimationFrame(loop);}
  });
  stopBtn.addEventListener('click', ()=>running=false);

  canvas.addEventListener('click', evt=>{
    const rect=canvas.getBoundingClientRect();
    const x=evt.clientX-rect.left;
    const y=evt.clientY-rect.top;
    const c=Math.floor(x/cellSize);
    const r=Math.floor(y/cellSize);
    if(r>=0&&r<rows&&c>=0&&c<cols){
      const cell=grid[r][c];
      cell.alive=!cell.alive;
      cell.age=cell.alive?1:0;
      cell.dying=false;
    }
  });

  ctx.font='10px serif';
  ctx.textBaseline='top';
  draw();
}
</script>

