n toggleCell(mx,my){const x=Math.floor(mx/cellSize),y=Math.floor(my/cellSize);if(x<0||x>=cols||y<0||y>=rows)return;const cell=grid[y][x];if(cell.alive){cell.alive=false;cell.age=0;cell.fade=1;}else{cell.alive=true;cell.age=1;cell.fade=0;}}canvas.addEventListener('click',(e)=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;toggleCell(mx,my);});function randomize(){for(let y=0;y<rows;y++){for(let x=0;x<cols;x++){grid[y][x].alive=Math.random()<0.2;grid[y][x].age=grid[y][x].alive?1:0;grid[y][x].fade=0;}}}function clearGrid(){for(let y=0;y<rows;y++){for(let x=0;x<cols;x++){grid[y][x].alive=false;grid[y][x].age=0;grid[y][x].fade=0;}}}const ctrlDiv=document.createElement('div');ctrlDiv.style.margin='10px 0';canvas.parentNode.insertBefore(ctrlDiv,canvas.nextSibling);const patternSelect=document.createElement('select');['None','Glider','Blinker','GosperGun','Pulsar'].forEach(p=>{const o=document.createElement('option');o.value=p;o.textContent=p;patternSelect.appendChild(o);});ctrlDiv.appendChild(patternSelect);const speedLabel=document.createElement('label');speedLabel.textContent='Speed:';ctrlDiv.appendChild(speedLabel);const speedSlider=document.createElement('input');speedSlider.type='range';speedSlider.min='1';speedSlider.max='10';speedSlider.value='5';speedSlider.style.margin='0 5px';ctrlDiv.appendChild(speedSlider);const randBtn=document.createElement('button');randBtn.textContent='Randomize';ctrlDiv.appendChild(randBtn);const clearBtn=document.createElement('button');clearBtn.textContent='Clear';ctrlDiv.appendChild(clearBtn);speedSlider.addEventListener('input',()=>{speed=parseInt(speedSlider.value,10);});randBtn.addEventListener('click',randomize);clearBtn.addEventListener('click',clearGrid);const patterns={Glider:[[0,1],[1,2],[2,0],[2,1],[2,2]],Blinker:[[0,-1],[0,0],[0,1]],GosperGun:[[0,0],[1,0],[0,1],[1,1],[10,0],[10,1],[10,2],[11,-1],[11,3],[12,-2],[12,4],[13,0],[13,1],[13,2],[13,3],[14,0],[14,1],[14,2],[14,3],[15,1],[16,-1],[16,3],[17,0],[17,1],[17,2],[18,1],[20,0],[20,1],[20,2],[21,0],[21,1],[21,2],[22,-1],[22,3],[23,-2],[23,4],[24,0],[24,1],[24,2],[25,0],[25,1],[25,2],[26,1],[28,0],[28,1],[29,-1],[29,2],[30,-2],[30,3],[31,-1],[31,1],[31,2],[32,0],[32,1],[33,0],[33,1],[34,0],[34,1],[35,0],[35,1],[36,0],[36,1],[37,0],[37,1],[38,0],[38,1],[39,0],[39,1],[40,0],[40,1],[41,0],[41,1]] ,Pulsar:[[ -6,-4],[-6,-3],[-6,-2],[-6,2],[-6,3],[-6,4],[-5,-6],[-5,-1],[-5,1],[-5,6],[-4,-6],[-4,-1],[-4,1],[-4,6],[-3,-6],[-3,-1],[-3,1],[-3,6],[-2,-6],[-2,-1],[-2,1],[-2,6],[-1,-6],[-1,-1],[-1,1],[-1,6],[0,-4],[0,-3],[0,-2],[0,2],[0,3],[0,4] ]};function placePattern(name,mx,my){const rel=patterns[name];if(!rel)return;const cx=Math.floor(mx/cellSize),cy=Math.floor(my/cellSize);rel.forEach(([dx,dy])=>{const x=(cx+dx+cols)%cols,y=(cy+dy+rows)%rows;grid[y][x].alive=true;grid[y][x].age=1;grid[y][x].fade=0;});}canvas.addEventListener('dblclick',(e)=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;const pat=patternSelect.value;if(pat!=='None')placePattern(pat,mx,my);});}

